/** Function decode range angka registrasi jenis kendaraan */
function decodeJenisKendaraan(numStr: string): string | undefined {
  const num = Number.parseInt(numStr, 10);
  if (Number.isNaN(num)) return undefined;

  if (num >= 1 && num <= 1999) return "Mobil Penumpang / Pribadi";
  if (num >= 2000 && num <= 6999) return "Sepeda Motor";
  if (num >= 7000 && num <= 7999) return "Bus / Kendaraan Umum";
  if (num >= 8000 && num <= 8999) return "Kendaraan Beban / Truk";
  if (num >= 9000 && num <= 9999) return "Kendaraan Khusus / Operasional";
  return undefined;
}

/** Decode full atau partial plat nomor string */
export function readPlatFull(rawInput: string): PlatRecord | undefined {
  const trimmed = rawInput.trim().toUpperCase();
  const parts = trimmed.split(/\s+/);

  const mainKode = parts[0] || "";
  const numStr = parts[1] || "";
  const seriStr = parts[2] || "";

  const record = platMap.get(mainKode);
  if (!record) return undefined;

  let subWil: string | undefined = undefined;
  if (seriStr.length >= 1 && SUB_WILAYAH_MAP[mainKode]) {
    const firstSeriChar = seriStr[0];
    subWil = SUB_WILAYAH_MAP[mainKode][firstSeriChar];
  }

  let jenis: string | undefined = undefined;
  if (numStr) {
    jenis = decodeJenisKendaraan(numStr);
  }

  return {
    ...record,
    subWilayah: subWil,
    jenisKendaraan: jenis,
  };
}

export function readPlat(kode: string): PlatRecord | undefined {
  return readPlatFull(kode);
}
